            case "CursorMoved": self = try .cursorMoved(identity: fields.decode("identity", String.self))
            case "ElementAdded": self = try .elementAdded(id: fields.decode("id", String.self))
            case "ElementDeleted": self = try .elementDeleted(id: fields.decode("id", String.self))
